CREATE TABLE "AdminUser" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "name" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AdminUser_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AdminUser_email_key" ON "AdminUser"("email");
CREATE TABLE "Session" ("id" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "adminUserId" TEXT NOT NULL, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash"); CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE TABLE "SiteContent" ("id" TEXT NOT NULL, "brandName" TEXT NOT NULL, "phone" TEXT NOT NULL, "email" TEXT NOT NULL, "address" TEXT NOT NULL, "description" TEXT NOT NULL, "hero" JSONB NOT NULL, "about" JSONB NOT NULL, "stats" JSONB NOT NULL, "services" JSONB NOT NULL, "testimonials" JSONB NOT NULL, "footer" JSONB NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SiteContent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Property" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "type" TEXT NOT NULL, "status" TEXT NOT NULL, "location" TEXT NOT NULL, "price" INTEGER, "priceLabel" TEXT, "shortDescription" TEXT, "description" TEXT NOT NULL, "bedrooms" INTEGER, "bathrooms" INTEGER, "area" TEXT, "plotSize" TEXT, "images" JSONB NOT NULL, "amenities" JSONB NOT NULL, "featured" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Property_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Property_slug_key" ON "Property"("slug"); CREATE INDEX "Property_status_idx" ON "Property"("status"); CREATE INDEX "Property_type_idx" ON "Property"("type"); CREATE INDEX "Property_location_idx" ON "Property"("location"); CREATE INDEX "Property_featured_idx" ON "Property"("featured");
CREATE TABLE "Estate" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "location" TEXT NOT NULL, "description" TEXT NOT NULL, "startingPrice" TEXT, "image" TEXT NOT NULL, "gallery" JSONB NOT NULL, "amenities" JSONB NOT NULL, "featured" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Estate_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Estate_slug_key" ON "Estate"("slug"); CREATE INDEX "Estate_featured_idx" ON "Estate"("featured"); CREATE INDEX "Estate_location_idx" ON "Estate"("location");
CREATE TABLE "Lead" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "phone" TEXT, "interest" TEXT, "message" TEXT, "source" TEXT, "status" TEXT NOT NULL DEFAULT 'NEW', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Lead_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Lead_status_idx" ON "Lead"("status"); CREATE INDEX "Lead_createdAt_idx" ON "Lead"("createdAt");
CREATE TABLE "Post" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "excerpt" TEXT NOT NULL, "content" TEXT NOT NULL, "image" TEXT, "published" BOOLEAN NOT NULL DEFAULT false, "publishedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Post_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Post_slug_key" ON "Post"("slug"); CREATE INDEX "Post_published_idx" ON "Post"("published");
ALTER TABLE "Session" ADD CONSTRAINT "Session_adminUserId_fkey" FOREIGN KEY ("adminUserId") REFERENCES "AdminUser"("id") ON DELETE CASCADE ON UPDATE CASCADE;
